/* ===== EDIT YOUR CONTENT HERE ===== */
const C={
  name:"Sneha",
  secret:"loveyou",
  hint:"Three words, said softly.",
  code:"1221",
  video:"data:video/mp4;base64,",
  endVideo:"data:video/mp4;base64,",
  quiz:[
    {q:"Where did we first meet?",a:["in my heart","my heart","heart"],h:"Think of the place where I keep you."},
    {q:"What is your name at first?",a:["Mylove","My love"],h:"Think of the sweetest name I call you."},
    {q:"What is our best memorable date?",a:["04.03.2020","4.3.2020"],h:"Type it as DD.MM.YYYY."}
  ],
  photos:[
    {src:"data:image/jpeg;base64,",r:0.7500,m:"Golden light, a purple saree, and a smile that makes everything else fade away. Happy birthday, Sneha."},
    {src:"data:image/jpeg;base64,",r:1.3333,m:"With you, even a train platform feels like the start of a beautiful story."},
    {src:"data:image/jpeg;base64,",r:1.1976,m:"Warm lights, good company, and you smiling right beside me. Some moments don’t need words."},
    {src:"data:image/jpeg;base64,",r:1.4006,m:"My favourite place in the whole world is inside this hug."},
    {src:"data:image/jpeg;base64,",r:1.3333,m:"I could keep looking at you like this forever, and still never run out of reasons to smile."}
  ],
  letter:[
    "Happy birthday, Sneha.",
    "Today is not just another day on the calendar. It is the day the world became softer, kinder and a little more beautiful, because you were born into it.",
    "Since 04.03.2020, my days have had a different colour. You turned ordinary moments into memories I would choose again and again.",
    "Thank you for your smile, your patience, and the way you make a quiet place feel like home. Thank you for being my Mylove.",
    "I wish you laughter that never runs out, dreams that keep coming true, and a year as lovely as you are.",
    "Always yours, with all my heart."
  ],
  final:"Happy Birthday, Sneha! You are my favourite person, today and every day. This whole world was made for you. I love you, my Mylove."
};
/* ================================== */
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const order=['intro','door','garden','video','puzzles','memories','letter','celebrate','final'];
const names={intro:'Welcome',door:'The door',garden:'The garden',video:'A moment',puzzles:'Puzzles',memories:'Memories',letter:'The letter',celebrate:'Celebration',final:'The surprise'};
let st={scene:'intro',g:[],p:0,m:0,out:0};
try{Object.assign(st,JSON.parse(localStorage.getItem('bd-surprise')||'{}'))}catch(e){}
const save=()=>{try{localStorage.setItem('bd-surprise',JSON.stringify(st))}catch(e){}};
let snd=true,ac;
function chime(f=660){if(!snd)return;try{ac=ac||new AudioContext();const o=ac.createOscillator(),g=ac.createGain();o.frequency.value=f;g.gain.setValueAtTime(.1,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.7);o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+.7)}catch(e){}}
$('#snd').onclick=e=>{snd=!snd;$('#bgv').muted=!snd;e.target.textContent=snd?'Sound on':'Sound off';e.target.setAttribute('aria-pressed',snd)};
function go(id){st.scene=id;save();$$('.scene').forEach(s=>s.classList.toggle('on',s.id===id));$('#bar').style.width=order.indexOf(id)/(order.length-1)*100+'%';$('#where').textContent=names[id];(init[id]||(()=>{}))()}
$('#reset').onclick=()=>{st={scene:'intro',g:[],p:0,m:0,out:0};save();location.reload()};
const norm=s=>s.toLowerCase().replace(/[^a-z0-9]/g,'');
const init={};

/* intro + door */
$('#hello').textContent='Hello, '+C.name;
$('#door1').onclick=()=>{chime(520);go('door')};
$('#hint1').textContent='Type the secret word to come inside. Hint: '+C.hint;
let tries=0;
function tryDoor(){if(norm($('#word').value)===norm(C.secret)){chime(784);go('garden')}else{tries++;$('#word').classList.remove('shake');void $('#word').offsetWidth;$('#word').classList.add('shake');$('#doorMsg').textContent=tries>1?'Not quite. Think of '+C.hint.toLowerCase():'That word doesn’t open the door. Try again.';chime(220)}}
$('#enter').onclick=tryDoor;$('#word').onkeydown=e=>{if(e.key==='Enter')tryDoor()};

/* garden */
const items=[['🌸',12,150,0],['🌷',44,190,0],['🌻',74,140,0],['🦋',24,40,1],['✨',82,60,1]];
init.garden=()=>{const f=$('#field');f.innerHTML='';items.forEach((it,i)=>{const b=document.createElement('button');b.className=(it[3]?'hid':'fl')+(st.g.includes(i)?' hit':'');b.textContent=it[0];b.style.cssText+=`left:${it[1]}%;top:${it[2]}px`;b.setAttribute('aria-label',it[3]?'A hidden thing':'A sleeping flower');if(it[3]&&st.g.includes(i))b.style.opacity=1;b.onclick=()=>{if(!st.g.includes(i)){st.g.push(i);save();chime(520+i*90)}b.classList.add('hit');b.style.opacity=1;upd()};f.appendChild(b)});upd()};
let gdone=0;
function upd(){$('#gc').textContent=st.g.length+' of 5';if(st.g.length>=5&&!gdone){gdone=1;setTimeout(()=>go('video'),1600)}}
/* cinematic video */
init.video=()=>{const v=$('#vid'),next=()=>{if(st.scene==='video')go('puzzles')};
  if(C.video){v.src=C.video;$('#plate').hidden=true;v.onended=next;v.onerror=()=>setTimeout(next,4000);v.play().catch(()=>{v.muted=true;v.play().catch(()=>setTimeout(next,4000))});setTimeout(next,45000)}
  else setTimeout(next,5000)};

/* puzzles: 22 stars -> 3 quiz questions */
const shuffle=a=>a.map(v=>[Math.random(),v]).sort((x,y)=>x[0]-y[0]).map(v=>v[1]);
init.puzzles=()=>{const b=$('#pBody'),n=C.quiz.length,sky=$('#sky');b.innerHTML='';sky.innerHTML='';b.hidden=false;
  if(st.p>n){go('memories');return}
  if(st.p===0){const T=22;let lit=0;b.hidden=true;const t=$('#pTitle');t.textContent='Light up the sky: 0 of '+T;
    const cells=[];for(let r=0;r<4;r++)for(let c=0;c<6;c++)cells.push([r,c]);
    shuffle(cells).slice(0,T).forEach(([r,c])=>{const s=document.createElement('button');s.className='st';s.textContent='⭐';s.setAttribute('aria-label','Star');s.style.left=(4+(c+Math.random()*.7)*15.3)+'%';s.style.top=(12+(r+Math.random()*.7)*19)+'%';
      s.onclick=()=>{if(s.classList.contains('hit'))return;s.classList.add('hit');chime(500+lit*35);lit++;t.textContent='Light up the sky: '+lit+' of '+T;if(lit===T){burst();setTimeout(()=>{st.p=1;save();init.puzzles()},1100)}};sky.appendChild(s)})}
  else{const qi=st.p-1,q=C.quiz[qi];let tr=0;$('#pTitle').textContent='Question '+st.p+' of '+n;
    b.innerHTML=`<p><strong>${q.q}</strong></p><div class="opts"><input id="qa" autocomplete="off" aria-label="Your answer" placeholder="Type your answer" style="width:100%"><div class="msg" id="qm"></div><button class="btn" id="qb">Check</button></div>`;
    const chk=()=>{const v=norm($('#qa').value);if(q.a.some(a=>norm(a)===v)){chime(784);$('#qm').textContent='That’s right.';setTimeout(()=>{st.p++;save();init.puzzles()},800)}else{tr++;$('#qa').classList.remove('shake');void $('#qa').offsetWidth;$('#qa').classList.add('shake');$('#qm').textContent=tr>1?'Hint: '+q.h:'Not quite. Try again.';chime(220)}};
    $('#qb').onclick=chk;$('#qa').onkeydown=e=>{if(e.key==='Enter')chk()};setTimeout(()=>$('#qa').focus(),60)}
};

/* photos: one at a time, message on the back */
function showPhoto(){const i=st.m,p=C.photos[i],N=C.photos.length;
  $('#pCount').textContent='Photo '+(i+1)+' of '+N;$('#pNext').hidden=true;
  $('#pc').innerHTML=`<div class="flip" id="flip" style="aspect-ratio:${p.r||.8};height:min(54vh,calc(86vw / ${p.r||.8}))"><div class="inner"><div class="face front">${p.src?`<img src="${p.src}" alt="Photo ${i+1}">`:'<span>📷<br>Photo '+(i+1)+'</span>'}</div><div class="face back"><span>${p.m}</span></div></div></div>`;
  $('#flip').onclick=e=>{if(e.currentTarget.classList.contains('open'))return;e.currentTarget.classList.add('open');chime(600+i*80);$('#pNext').textContent=i===N-1?'Open the letter':'Next photo';setTimeout(()=>$('#pNext').hidden=false,900)}}
init.memories=()=>{st.m=Math.min(st.m,C.photos.length-1);showPhoto()};
$('#pNext').onclick=()=>{if(st.m>=C.photos.length-1)go('letter');else{st.m++;save();showPhoto()}};

/* letter: line-by-line reveal */
$('#paper').innerHTML=C.letter.map((p,i)=>`<p style="animation-delay:${.5+i*1.5}s">${p}</p>`).join('');
$('#env').onclick=()=>{chime(700);$('#env').classList.add('go');setTimeout(()=>{$('#env').hidden=true;$('#paper').hidden=false},650);setTimeout(()=>{$('#lDone').hidden=false;chime(880)},650+500+C.letter.length*1500+800)};
$('#lDone').onclick=()=>go('celebrate');

/* celebrate: gift -> bigger cake -> candles -> wish -> scratch card */
function candles(){const c=$('#candles');c.innerHTML='';for(let i=0;i<3;i++){const b=document.createElement('button');b.className='cd';b.textContent='🕯️';b.setAttribute('aria-label','Candle');b.onclick=()=>out(b);c.appendChild(b)}}
let outN=0;
function out(b){if(b.classList.contains('out'))return;b.classList.add('out');chime(400);if(++outN===3)done()}
function done(){stopMic();burst();chime(880);$('#mic').hidden=$('#manual').hidden=true;$('#cakeBox').hidden=true;$('#cTitle').textContent='Your wish';$('#wishBox').hidden=false;
  setTimeout(()=>{$('#wishBox').hidden=true;$('#cTitle').textContent='One last thing';$('#scratchBox').hidden=false;setupScratch(false)},3400)}
$('#gift').onclick=()=>{chime(660);$('#gift').hidden=true;$('#cakeBox').hidden=false;$('#mic').hidden=$('#manual').hidden=false;$('#cTitle').textContent='Make a wish';candles()};
$('#manual').onclick=()=>$$('.cd').forEach(out);
let stream,raf;
function stopMic(){cancelAnimationFrame(raf);stream&&stream.getTracks().forEach(t=>t.stop())}
$('#mic').onclick=async()=>{try{stream=await navigator.mediaDevices.getUserMedia({audio:true});ac=ac||new AudioContext();const a=ac.createAnalyser();a.fftSize=512;ac.createMediaStreamSource(stream).connect(a);const d=new Uint8Array(a.fftSize);$('#cMsg').textContent='Take a deep breath and blow.';$('#mic').hidden=true;
  const loop=()=>{a.getByteTimeDomainData(d);let m=0;d.forEach(v=>m=Math.max(m,Math.abs(v-128)));if(m>70){$$('.cd').forEach(out)}else raf=requestAnimationFrame(loop)};loop()}catch(e){$('#cMsg').textContent='No microphone access. Tap the candles instead.';$('#mic').hidden=true}};
function setupScratch(revealed){const c=$('#sc'),g=c.getContext('2d');$('#codeShow').textContent=C.code;
  if(revealed){c.style.opacity=0;c.style.pointerEvents='none';$('#cNext').hidden=false;return}
  const gr=g.createLinearGradient(0,0,300,110);gr.addColorStop(0,'#cfc6d6');gr.addColorStop(.5,'#f2edf5');gr.addColorStop(1,'#b8adc2');g.fillStyle=gr;g.fillRect(0,0,300,110);g.fillStyle='#665c68';g.font='600 16px Inter,sans-serif';g.textAlign='center';g.fillText('Scratch here',150,62);
  let down=0,n=0,fin=0;g.globalCompositeOperation='destination-out';
  const check=()=>{const d=g.getImageData(0,0,300,110).data;let t=0;for(let i=3;i<d.length;i+=16)if(d[i]===0)t++;if(t/(d.length/16)>.5){fin=1;c.style.opacity=0;c.style.pointerEvents='none';chime(988);burst();st.out=1;save();$('#cNext').hidden=false}};
  const sc=e=>{if(!down||fin)return;const r=c.getBoundingClientRect();g.beginPath();g.arc((e.clientX-r.left)*300/r.width,(e.clientY-r.top)*110/r.height,20,0,7);g.fill();if(++n%5===0)check()};
  c.onpointerdown=e=>{down=1;c.setPointerCapture(e.pointerId);sc(e)};c.onpointermove=sc;c.onpointerup=()=>down=0}
init.celebrate=()=>{outN=0;if(st.out){$('#gift').hidden=true;$('#cakeBox').hidden=true;$('#cTitle').textContent='One last thing';$('#scratchBox').hidden=false;setupScratch(true)}};
$('#cNext').onclick=()=>go('final');

/* final */
function showEnd(){const f=$('#fbg'),v=$('#bgv');$('#final').classList.add('rev');document.body.classList.add('fin');v.src=C.endVideo;v.muted=!snd;f.style.display='block';requestAnimationFrame(()=>requestAnimationFrame(()=>f.style.opacity=1));v.play().catch(()=>{v.muted=true;v.play().catch(()=>{})})}
function tryCode(){if(norm($('#rcode').value)===norm(C.code)){$('#lock').style.display='none';showEnd();$('#finalMsg').hidden=false;$('#finalMsg').textContent=C.final;burst();chime(988)}else{$('#rMsg').textContent='That code doesn’t match. Check the cake.';chime(220)}}
$('#reveal').onclick=tryCode;$('#rcode').onkeydown=e=>{if(e.key==='Enter')tryCode()};

/* atmosphere: petals + confetti */
const cv=$('#bg'),x=cv.getContext('2d');let W,H,parts=[],conf=[];
const rm=matchMedia('(prefers-reduced-motion:reduce)').matches;
function size(){W=cv.width=innerWidth*devicePixelRatio;H=cv.height=innerHeight*devicePixelRatio}
addEventListener('resize',size);size();
const cols=['#c8788c','#a98fbd','#8cafc0','#f2b8c6'];
for(let i=0;i<(rm?0:34);i++)parts.push({x:Math.random()*W,y:Math.random()*H,r:(3+Math.random()*5)*devicePixelRatio,v:.3+Math.random()*.6,s:Math.random()*6,c:cols[i%4]});
function burst(){for(let i=0;i<(rm?0:140);i++)conf.push({x:W/2,y:H*.4,vx:(Math.random()-.5)*16*devicePixelRatio,vy:(-Math.random()*14-3)*devicePixelRatio,r:(4+Math.random()*5)*devicePixelRatio,c:cols[i%4],l:1})}
function tick(t){x.clearRect(0,0,W,H);parts.forEach(p=>{p.y+=p.v*devicePixelRatio;p.x+=Math.sin(t/1500+p.s)*.6*devicePixelRatio;if(p.y>H+10){p.y=-10;p.x=Math.random()*W}x.globalAlpha=.4;x.fillStyle=p.c;x.beginPath();x.ellipse(p.x,p.y,p.r,p.r*.6,p.s,0,7);x.fill()});
  conf=conf.filter(c=>c.l>0);conf.forEach(c=>{c.x+=c.vx;c.y+=c.vy;c.vy+=.35*devicePixelRatio;c.l-=.008;x.globalAlpha=Math.max(c.l,0);x.fillStyle=c.c;x.fillRect(c.x,c.y,c.r,c.r*.6)});requestAnimationFrame(tick)}
requestAnimationFrame(tick);

go(st.scene);
